import assert from 'node:assert/strict';import {createRequire} from 'node:module';import {mkdirSync,mkdtempSync,rmSync,writeFileSync} from 'node:fs';import {join,resolve} from 'node:path';import {tmpdir} from 'node:os';import {pathToFileURL} from 'node:url';
const root=resolve(process.env.HE_SOURCE_ROOT),require=createRequire(join(root,'package.json')),Database=require('better-sqlite3');const ledger=await import(pathToFileURL(join(root,'src/memory/recovery/ledger.ts')));assert.equal(process.version,'v24.22.1');
const cases=[];for(const name of ['success-repeat','callback-failure-retry','commit-failure-repeat','copy-ticket','foreign-handle','authority-advanced','begin-in-transaction']){const dir=mkdtempSync(join(tmpdir(),'meme-durable-'));mkdirSync(join(dir,'live'));const path=join(dir,'live','main.sqlite'),db=new Database(path),authority=ledger.enroll(db,path,join(dir,'authority'));ledger.bindRecovery(db,authority);db.pragma('foreign_keys=ON');db.exec('CREATE TABLE effects(id TEXT PRIMARY KEY);CREATE TABLE parent(id INTEGER PRIMARY KEY);CREATE TABLE child(id INTEGER REFERENCES parent(id) DEFERRABLE INITIALLY DEFERRED)');const steps=[];let ticket;const take=(action,fn)=>{let error,result;try{result=fn()??null}catch(e){error=e.message};steps.push({action,result:result??null,...(error?{error}:{}),main:ledger.metadata(db).head.sequence,authority:authority.head().sequence,effects:db.prepare('SELECT id FROM effects ORDER BY id').all().map(r=>r.id),child:db.prepare('SELECT count(*) n FROM child').get().n})};try{
 if(name==='begin-in-transaction'){take('begin',()=>db.transaction(()=>ledger.beginDurableRevocation(db,{kind:'source',sceneId:'s',messageId:'m'}))())}else{take('begin',()=>{ticket=ledger.beginDurableRevocation(db,{kind:'source',sceneId:'s',messageId:'m'})});if(name==='success-repeat'){take('commit',()=>ledger.commitDurableRevocation(db,ticket,()=>db.prepare('INSERT INTO effects VALUES(?)').run('one')&&null));take('repeat',()=>ledger.commitDurableRevocation(db,ticket,()=>null))}if(name==='callback-failure-retry'){take('failure',()=>ledger.commitDurableRevocation(db,ticket,()=>{db.prepare('INSERT INTO effects VALUES(?)').run('one');throw Error('synthetic_apply_failure')}));take('retry',()=>ledger.commitDurableRevocation(db,ticket,()=>db.prepare('INSERT INTO effects VALUES(?)').run('two')&&null))}if(name==='commit-failure-repeat'){take('commit-failure',()=>ledger.commitDurableRevocation(db,ticket,()=>db.exec('INSERT INTO child VALUES(99)')&&null));take('repeat',()=>ledger.commitDurableRevocation(db,ticket,()=>null))}if(name==='copy-ticket')take('copy',()=>ledger.commitDurableRevocation(db,{...ticket},()=>null));if(name==='foreign-handle'){const other=new Database(path);take('foreign',()=>ledger.commitDurableRevocation(other,ticket,()=>null));other.close()}if(name==='authority-advanced'){authority.append({kind:'source',sceneId:'s',messageId:'new'},authority.head(),true);take('changed',()=>ledger.commitDurableRevocation(db,ticket,()=>null))}}
 cases.push({name,steps})
 }finally{db.close();authority.close();rmSync(dir,{recursive:true,force:true})}}
writeFileSync(new URL('durable-oracle.json',import.meta.url),JSON.stringify({node:process.version,cases},null,2)+'\n');console.log(`${cases.length} actual split durable source traces`)
